      "rarity": "common",
      "traits": [
        "agile",
        "deadly-d6",
        "finesse"
      ],
      "description": "Developed by Alkenstar scouts who often don't have time to break down a Tripod when beset by the chaotic mutant monsters of the Mana Wastes, this two-pronged stabbing weapon can be used as a bipod to stabilize a gun with potent kickback. A forked bipod can be deployed or retrieved for use as a melee weapon as an Interact action. As with a Tripod, you can change your grip on the weapon as part of this action.",
