    "data": {
      "schemaVersion": 1,
      "name": "Bomb Launcher",
      "itemType": "equipment",
      "level": 1,
      "rarity": "uncommon",
      "traits": [],
      "description": "This long, hollow tube is held in two hands and braced over the shoulder. Inside, it contains a small metal basket sized to hold alchemical bombs. A chute in the top delivers an alchemical bomb into the internal basket, while a lever on the underside pulls the basket back and locks it in place. Loading an alchemical bomb into a bomb launcher requires a single Interact action. With a pull of a trigger, the basket speeds forward, allowing you to Strike with the loaded alchemical bomb over long distances. Bombs fired with a bomb launcher have a range increment of 60 feet.",
      "bulk": 1,
      "price": {
        "gp": 20
      },
      "usage": "held-in-two-hands",
      "category": "equipment",
      "group": "equipment"
    }
