      "itemType": "consumable",
      "level": 3,
      "rarity": "uncommon",
      "traits": [
        "consumable",
        "gadget"
      ],
      "description": "Activate 2 (manipulate)\nAn etheric essence disruptor emits bursts of discordant ethereal energy through a process based upon Stasian etheric-spirit singers, though without the need for a Stasian coil. Etheric essence disruptors attempt to break down the workings of a spell that manipulates spiritual essence. Upon activation, attempt to counteract an active divine or occult spell within 30 feet, with a 1d20+7 counteract modifier and a counteract rank of 2.",
      "bulk": 1,
      "price": {
        "gp": 12
      },
      "usage": "held-in-one-hand",
