    "data": {
      "schemaVersion": 1,
      "name": "Timepiece (Grand Clock)",
      "itemType": "equipment",
      "level": 3,
      "rarity": "uncommon",
      "traits": [
        "clockwork"
      ],
      "description": "Clockwork timepieces come in a variety of sizes and aesthetic styles, but they're all designed to display the accurate time of day down to the second.\nClockwork timepieces have a 24-hour activation cycle, after which they must wound in a process that takes 1 minute to complete.\nThese towering, ten-foot-tall clocks have been painstakingly handcrafted by skilled artisans and feature loud chimes that can be heard hourly throughout a manor. Owners of grand clocks usually tend to display them prominently in a study, lounge area, or foyer.",
      "bulk": 16,
      "price": {
        "gp": 50
      },
      "usage": "held-in-one-hand",
      "category": "equipment",
      "group": "equipment"
    }
