      "description": "Ammunition round\nActivate 1 (manipulate)\nThese cartridges are filled with sticky clear glue. When a glue bullet hits, a syrupy webbing coats the target and sticks to the ground or a nearby surface, hindering their movement. The target takes a –10-foot circumstance penalty to its Speeds for 2d4, or until it Escape DC 18 against a DC of 18. On a critical hit, the target is also Immobilized until it Escapes.\nEffect: Glue Bullet",
