      "description": "Ammunition round\nActivate 2 (concentrate)\nThese bullets glimmer with emerald green light that dances across the surface of the bullet like a mischievous sprite. On a successful Strike, a fairy bullet casts Revealing Light (check (reflex, dc:23)) extending outward from a corner of the target's space. You choose which corner of the target's space you want the burst to extend out from at the time you declare the associated Strike. Since the fairy bullet is fired before revealing light can reveal the target, the effects don't affect the flat check for the attack roll with the fairy bullet if the target is Hidden from you.",
