      "rarity": "uncommon",
      "traits": [
        "consumable",
        "gadget"
      ],
      "description": "Ablative armor plating is additional plating, combined with springs, clever clockwork, and improvised padding, to absorb damage by knocking the additional pieces free. The pieces slowly come apart on their own with time and movement. The process of attaching the plating takes 10 minutes and grants the wearer of the armor the 20 temporary Hit Points for 1 hour or until lost. Removing the plating early destroys it.\nEffect: Ablative Armor Plating (Greater)",
