      "itemType": "consumable",
      "level": 9,
      "rarity": "uncommon",
      "traits": [
        "clockwork",
        "consumable",
        "gadget"
      ],
      "description": "Activate 2 (manipulate)\nGecko pads are thin, clockwork devices shaped like palms, which can be strapped onto existing handwear or a creature's hands. When activated, they whir to life and improve your grip on surfaces, while slowly releasing a sticky substance stored within the device's surface to help you climb. The pads give you a climb Speed equal to your Speed as long as your hands are free.\nThe climb Speed lasts for 1 hour.",
