      "rarity": "uncommon",
      "traits": [
        "consumable",
        "mechanical",
        "snare",
        "trap"
      ],
      "description": "When a creature enters the snare's square, several strands of strong wires ending in jagged hooks latch onto it before hauling it to the ground. The snare deals 2d6 piercing damage, and the targeted creature must attempt a check (reflex, showDC:all, dc:28) save.\nCritical Success The creature is unaffected.\nSuccess The creature takes half damage.\nFailure The creature takes full damage and is knocked Prone and Immobilized for 1 round (Escape DC 28).\nCritical Failure The creature takes double damage, is knocked prone, and is Restrained for 1 round (Escape DC 28).",
