      "description": "Activate 2 (manipulate)\nA material essence disruptor emits bursts of disordered energy to break down the structure of a spell that manipulates material essence. Attempt to counteract an active arcane or primal spell within 60 feet, with a 1d20+18 counteract modifier and a counteract rank of 6.",
