      "itemType": "ammunition",
      "level": 12,
      "rarity": "common",
      "traits": [
        "alchemical",
        "consumable"
      ],
      "description": "Ammunition any\nActivate 1 (manipulate)\nThis ammunition includes a small reservoir of a tacky red substance that coats the ammunition when you activate it. The substance makes a creature bleed more freely. For 1 minute after you deal damage to a creature with an activated exsanguinating ammunition that creature gains weakness 5 to persistent bleed damage. In addition, the DC of any flat checks to end persistent bleed damage increases from 15 to 17 (from 10 to 12 when receiving particularly effective assistance) for the duration.\nEffect: Exsanguinating Ammunition",
      "bulk": 0,
