      "name": "Magnifying Scope (Major)",
      "itemType": "equipment",
      "level": 17,
      "rarity": "common",
      "traits": [
        "magical"
      ],
      "description": "These scopes use magically enhanced lenses to extend the range of your weapon and help spot distant foes. The scope grants you a +3 item bonus to visual Perception checks to Seek creatures through the scope.\nActivate—Zoom In 1 (manipulate)\nEffect You zoom in on your targets to make it easier to hit them at a distance. You increase the range increment of the weapon to which the scope is attached by 20 feet until the beginning of your next turn or until you're no longer wielding the weapon, whichever comes first.",
      "bulk": 0.1,
